package com.nigson.commerce.payment;

import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import com.nigson.commerce.order.OrderAuthority;
import com.nigson.commerce.pricing.PricingAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;

/** Local finance commands and private reads; approval never holds locks across provider HTTP. */
public final class PaymentService {
 private final PaymentRepository repository;private final OrderAuthority orders;private final PricingAuthority finance;private final PaymentPolicy policy;private final PlatformStore commands;private final AuditWriter audit;private final JdbcTemplate jdbc;private final TransactionTemplate reads;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public PaymentService(PaymentRepository repository,OrderAuthority orders,PricingAuthority finance,PaymentPolicy policy,PlatformStore commands,AuditWriter audit,JdbcTemplate jdbc,PlatformTransactionManager manager,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.repository=repository;this.orders=orders;this.finance=finance;this.policy=policy;this.commands=commands;this.audit=audit;this.jdbc=jdbc;this.clock=clock;this.metrics=metrics;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(2);}
 private void limits(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private void correlation(UUID id){ApiValues.uuid(id==null?null:id.toString());}
 public PaymentValues.Payment payment(ActorAssertion.Actor actor,UUID order){orders.owned(actor,order,false);return reads.execute(status->{limits();orders.owned(actor,order,false);return repository.payment(order);});}
 public PaymentValues.RefundDetail detail(ActorAssertion.Actor actor,UUID id){finance.require(actor,"FINANCE");return reads.execute(status->{limits();finance.require(actor,"FINANCE");return repository.detail(id);});}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String operation,String key,Object body,UUID correlation,java.util.function.Supplier<PlatformStore.Response> change){finance.require(actor,"FINANCE");policy.require();ApiValues.idempotencyKey(key);correlation(correlation);try{return commands.executeLocal(actor.party().toString(),operation,key,EventCodec.JSON.valueToTree(body),db->{limits();finance.stabilize(actor,"FINANCE");return change.get();});}catch(org.springframework.dao.DataAccessException failed){for(Throwable cause=failed;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failed;}}
 private void evidence(ActorAssertion.Actor actor,PaymentValues.Refund before,PaymentValues.Refund after,UUID correlation,boolean approval){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,approval?AuditValues.Action.REFUND_APPROVAL:AuditValues.Action.REFUND_REQUEST,AuditValues.Resource.REFUND,after.id(),correlation,AuditValues.Reason.OPERATOR_REQUEST,before==null?null:Map.of("state",before.state(),"version",before.version()),Map.of("state",after.state(),"version",after.version(),"amount",after.amount(),"currency",after.currency()),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.refund.commands","operation",approval?"APPROVAL":"REQUEST").increment();}});}
 private void event(UUID order,PaymentValues.Refund refund,String type,UUID correlation,String actor){var rows=jdbc.queryForList("SELECT organization_id FROM commerce.sales_order WHERE id=?",order);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);Instant now=clock.instant();var value=new LinkedHashMap<String,Object>();value.put("event_id",EventCodec.uuid7(now));value.put("event_type",type);value.put("schema_version",1);value.put("producer","commerce");value.put("occurred_at",now);value.put("aggregate_id",refund.id());value.put("aggregate_version",refund.version());value.put("organization_id",rows.getFirst().get("organization_id"));value.put("correlation_id",correlation);value.put("traceparent",null);value.put("payload",Map.of("refund_id",refund.id(),"order_id",order));commands.append(EventCodec.JSON.writeValueAsString(value),actor);}
 public PaymentValues.Refund request(ActorAssertion.Actor actor,UUID order,long version,PaymentValues.RefundInput input,String key,UUID correlation){finance.require(actor,"FINANCE");var response=execute(actor,"API-052",key,Map.of("order",order,"version",version,"input",input),correlation,()->{String business=EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("principal",actor.party(),"operation","API-052","key",key)));var refund=repository.request(order,version,input,business,actor.party());evidence(actor,null,refund,correlation,false);event(order,refund,"refund.requested.v1",correlation,actor.party().toString());return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(refund),refund.id());});return reads.execute(status->{limits();finance.require(actor,"FINANCE");return repository.refund(response.resource(),false);});}
 public PaymentValues.Refund approve(ActorAssertion.Actor actor,UUID id,long version,PaymentValues.Approval input,String key,UUID correlation){finance.require(actor,"FINANCE");repository.refund(id,false);var response=execute(actor,"API-053",key,Map.of("refund",id,"version",version,"input",input),correlation,()->{var before=repository.refund(id,false);var refund=repository.approve(id,version,input,actor.party(),policy.twoPerson());evidence(actor,before,refund,correlation,true);if(input.approve())event(repository.order(id),refund,"refund.approved.v1",correlation,actor.party().toString());return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(refund),refund.id());});return reads.execute(status->{limits();finance.require(actor,"FINANCE");return repository.refund(response.resource(),false);});}
}
